record Product(String name, double price, String category) {
    Product {
        if (price < 0) {
            throw new IllegalArgumentException("price must not be negative");
        }
    }

    double priceWithTax() {
        return price * 1.2;
    }
}

public class Shop {
    public static void main(String[] args) {
        Product pen = new Product("Pen", 2.5, "office");
        System.out.println(pen.name() + " costs " + pen.price());
        System.out.println(pen);
        System.out.println(pen.equals(new Product("Pen", 2.5, "office")));
        System.out.println(pen.priceWithTax());
        try {
            new Product("Broken", -1, "office");
        } catch (IllegalArgumentException e) {
            System.out.println(e.getMessage());
        }
    }
}

enum Size {
    SMALL(250), MEDIUM(350), LARGE(500);

    private final int millilitres;

    Size(int millilitres) {
        this.millilitres = millilitres;
    }

    int millilitres() {
        return millilitres;
    }
}

public class Cups {
    public static void main(String[] args) {
        Size order = Size.valueOf("MEDIUM");
        System.out.println(order + " holds " + order.millilitres() + " ml");
        System.out.println(order.ordinal() + " " + order.name());
        for (Size size : Size.values()) {
            String label = switch (size) {
                case SMALL -> "S";
                case MEDIUM -> "M";
                case LARGE -> "L";
            };
            System.out.print(label);
        }
        System.out.println();
        System.out.println(order == Size.MEDIUM);
    }
}

sealed interface Shape permits Circle, Square {}
record Circle(double radius) implements Shape {}
record Square(double side) implements Shape {}

public class Areas {
    static double area(Shape shape) {
        return switch (shape) {
            case Circle(double r) -> Math.PI * r * r;
            case Square(double s) -> s * s;
        };
    }

    static String classify(Shape shape) {
        return switch (shape) {
            case Circle c when c.radius() > 10 -> "big circle";
            case Circle c -> "circle";
            case Square s -> "square";
        };
    }

    public static void main(String[] args) {
        System.out.printf("%.2f%n", area(new Circle(1)));
        System.out.println(area(new Square(3)));
        System.out.println(classify(new Circle(12)));
        System.out.println(classify(new Square(2)));
    }
}

