import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.TreeMap;
import java.util.stream.Collectors;
import java.util.stream.IntStream;

public class Report {
    record Product(String name, double price, String category) {}

    public static void main(String[] args) {
        List<Product> products = List.of(
            new Product("Pen", 2.5, "office"),
            new Product("Notebook", 4.0, "office"),
            new Product("Mug", 8.0, "kitchen"),
            new Product("Kettle", 35.0, "kitchen"));

        List<String> cheap = products.stream()
            .filter(p -> p.price() < 10)
            .sorted(Comparator.comparingDouble(Product::price).reversed())
            .map(Product::name)
            .toList();
        System.out.println(cheap);

        double total = products.stream().mapToDouble(Product::price).sum();
        System.out.println(total);

        Map<String, Long> perCategory = products.stream()
            .collect(Collectors.groupingBy(Product::category, TreeMap::new, Collectors.counting()));
        System.out.println(perCategory);

        String names = products.stream().map(Product::name).collect(Collectors.joining(", "));
        System.out.println(names);

        System.out.println(IntStream.rangeClosed(1, 5).map(n -> n * n).sum());

        Optional<Product> priciest = products.stream().max(Comparator.comparingDouble(Product::price));
        System.out.println(priciest.map(Product::name).orElse("none"));
    }
}
